@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_biome_definition_list_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_biome_definition_list_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_981_reshape_changes_the_wire_past_the_gradients_first_field():
    assert GRADIENT_V975[:56] == GRADIENT_V1001[:56]
    assert GRADIENT_V975[56:57] != GRADIENT_V1001[56:57]


def test_the_pre_827_biome_id_carries_a_presence_byte():
    assert OPTIONAL_ID_V818[:3] + OPTIONAL_ID_V818[4:] == SPORES_AND_ASH
    assert OPTIONAL_ID_V818[3:4] == bytes.fromhex("01")
